{
  "steps": [
    {
      "task": "detect_and_extract_spatial_temporal",
      "player": "spatial_temporal_specialist",
      "rationale": "Detect temporal and spatial columns in the CSV and compute their extents to satisfy spatialCoverage and temporalCoverage requirements.",
      "inputs": {},
      "outputs": ["spatial_temporal_data"]
    },
    {
      "task": "generate_inaturalist_metadata",
      "player": "croissant_inaturalist_metadata_generator",
      "rationale": "Create the final Croissant iNaturalist metadata JSON using the computed spatial and temporal coverage.",
      "inputs": {
        "metadata_standard": "metadata_standard",
        "spatial_temporal": "spatial_temporal_data"
      },
      "outputs": ["metadata_output"]
    }
  ]
}

{
  "resource": "pityrogramma_calomelanos",
  "temporalCoverage": {
    "start": "1996-07-20T17:23:00+00:00",
    "end": "2026-06-08T09:18:11+00:00",
    "durationDays": 10914,
    "granularity": "seconds",
    "primaryTemporalColumn": "eventDate"
  },
  "spatialCoverage": {
    "boundingBox": {
      "minLatitude": -28.041467,
      "maxLatitude": 37.867024,
      "minLongitude": -171.443024,
      "maxLongitude": 168.311117,
      "crs": "EPSG:4326"
    },
    "centroid": {
      "lat": 10.153647485943774,
      "lon": 6.047245613453815
    },
    "coordinatePrecision": "≈0.000001° (~0.1 m) – derived from float64 storage (analyze_spatial_column)",
    "interpretationNote": "Typical positional uncertainty is 5‑20 m as indicated by the coordinateUncertaintyInMeters column."
  },
  "notes": [
    "eventDate is used for temporalCoverage because it records when each occurrence was observed/collected; dateIdentified and lastInterpreted are metadata timestamps and therefore excluded.",
    "All 996 records have valid decimalLatitude/decimalLongitude values; the spatial extent reflects the full geographic spread of the dataset.",
    "No tuple‑coord column is present; coordinates are provided as separate latitude and longitude columns in WGS‑84.",
    "lastInterpreted timestamps all fall within a single 50‑minute window on 2026‑06‑23, indicating they are batch‑processing metadata rather than observation dates."
  ]
}

